INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-1741959', 'course-bili-season-1741959', '100001', '0', 'BILI-DES-3D7H1Z', 'course-category-design', 'instructor-bili-407280684', '秀米排版作弊演示', '11 讲完整课程 · 1 小时 5 分钟', '嗨~我是叁叁，今天是一期情人节主题的公众号排版分享，同时给不会用秀米但想学的宝演示一下完整的快速排版过程，真的超省时间！这些我们可能会忽略的工具，为了让喜欢我分享的宝汁少走弯路，实打实的录一篇给你们看，', '课程简介：嗨~我是叁叁，今天是一期情人节主题的公众号排版分享，同时给不会用秀米但想学的宝演示一下完整的快速排版过程，真的超省时间！这些我们可能会忽略的工具，为了让喜欢我分享的宝汁少走弯路，实打实的录一篇给你们看，希望对你有帮助~ 一、工具：电脑+秀米（网页版） 二、颜色参数： ~主色：奶油白（F7F2DF）、浅淡绯红（E9C3AE） ~辅色：浓情巧克（6A1A11） ~点缀色：春日鲜绿（7C9252） （色卡来源：@色彩设计师张帅） · 三、排版步骤（仅供参考），具体看视频演示： 1、素材整理（图/文/配色/贴纸），布局构思 2、取色并保存 3、导入文档，设置全文属性（背景/图文格式） 4、版头设计 5、音乐组件/摘要设计 6、标题设计 7、正文/图片格式调整 · 看完记得练起来！不要在收藏夹里吃灰！课程结构：共 1 章 11 讲，累计时长 1 小时 5 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握设计软件的核心操作与高效工作流","理解版式、色彩、字体与视觉层级的基本原理","独立完成一套可放入作品集的完整设计项目","建立从需求沟通到设计交付的协作能力"]', '["零基础想入门设计的爱好者","需要系统提升视觉能力的运营与产品人员","设计专业在校学生"]', '["自备可运行设计软件的电脑","具备基础的审美观察与临摹耐心"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/4857aacae948e416e8cdebacc5c7e40b9e6072a6.jpg', '["设计创意","UI设计","平面设计","秀米排版作弊演示"]', 3547, 10, 188239, '4.6', 45329, 'BV1P84y1V7Eb', NULL, NULL, NULL, 1, 0, 'standard', NULL, '三三笔记', 0, 'tenant', 'published', '2023-02-08T17:40:49.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
