INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-4467743', 'course-bili-season-4467743', '100001', '0', 'BILI-DES-A1CUE0', 'course-category-design', 'instructor-bili-3493138152819508', '谷歌ux设计1《用户体验设计基础课程》foundation-of-ux-design（中英双字', '34 讲完整课程 · 234 小时 35 分钟', '用户体验（UX）设计基础是一系列七门课程中的第一门，将使你具备申请用户体验设计初级工作所需的技能。用户体验设计师专注于人们与网站、移动应用程序和实物等产品之间的互动。用户体验设计师使这些日常互动变得可用、愉快和无障碍。', '课程简介：用户体验（UX）设计基础是一系列七门课程中的第一门，将使你具备申请用户体验设计初级工作所需的技能。用户体验设计师专注于人们与网站、移动应用程序和实物等产品之间的互动。用户体验设计师使这些日常互动变得可用、愉快和无障碍。入门级用户体验设计师的角色可能包括同情用户，定义他们的痛点，提出设计解决方案的想法，原型和模拟，并测试设计以获得反馈。谷歌目前的用户体验设计师和研究人员将担任你的导师，你将完成模拟真实世界用户体验设计场景的实践活动。课程结构：共 1 章 34 讲，累计时长 234 小时 35 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握设计软件的核心操作与高效工作流","理解版式、色彩、字体与视觉层级的基本原理","独立完成一套可放入作品集的完整设计项目","建立从需求沟通到设计交付的协作能力"]', '["零基础想入门设计的爱好者","需要系统提升视觉能力的运营与产品人员","设计专业在校学生"]', '["自备可运行设计软件的电脑","具备基础的审美观察与临摹耐心"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/fc725097035132ed1f02a1a838ea3cc9f52df074.jpg', '["设计创意","UI设计","平面设计","谷歌ux设计1","用户体验设计基础课程","foundation"]', 844543, 34, 20051, '4.5', 8151, 'BV1Gs4y1q72X', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'GPT中英字幕课程资源', 0, 'tenant', 'published', '2023-06-03T13:23:14.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
