INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-6263571', 'course-bili-season-6263571', '100001', '0', 'BILI-DES-K8DTPQ', 'course-category-design', 'instructor-bili-356877173', '分享C4D零基础建模卡通IP人物教程', '9 讲完整课程 · 5 小时 9 分钟', '这是一个简单又可爱的卡通风IP人物模型，使用的都是常见工具和简单实用的方法完成建模，C4D R26版本。去年做的一个建模，花了几个小时做了录音和剪辑，希望大家喜欢，有什么意见或者疑问也可以留言交流。', '课程简介：这是一个简单又可爱的卡通风IP人物模型，使用的都是常见工具和简单实用的方法完成建模，C4D R26版本。去年做的一个建模，花了几个小时做了录音和剪辑，希望大家喜欢，有什么意见或者疑问也可以留言交流。课程结构：共 1 章 9 讲，累计时长 5 小时 9 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握设计软件的核心操作与高效工作流","理解版式、色彩、字体与视觉层级的基本原理","独立完成一套可放入作品集的完整设计项目","建立从需求沟通到设计交付的协作能力"]', '["零基础想入门设计的爱好者","需要系统提升视觉能力的运营与产品人员","设计专业在校学生"]', '["自备可运行设计软件的电脑","具备基础的审美观察与临摹耐心"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/d3ca6e69ceed946785f10ec997ad2983ef8cbfa3.jpg', '["设计创意","UI设计","平面设计"]', 18593, 9, 3910, '4.5', 815, 'BV1wTPSziECF', NULL, NULL, NULL, 1, 0, 'standard', NULL, '画师314', 0, 'tenant', 'published', '2026-03-09T07:08:27.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
