INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1xynv6feig', 'course-bili-bv1xynv6feig', '100001', '0', 'BILI-DES-28Q81R', 'course-category-design', 'instructor-bili-3546685005368073', 'Fusion 360 入门教程：从零开始进行 3D 建模', '9 讲完整课程 · 7 小时 31 分钟', '本课程并非围绕简单地死记硬背按钮和命令展开。其目标是帮助你理解3D模型是如何创建的，为什么存在不同的建模功能，以及在开始构建之前如何选择正确的方案。我们将从3D空间的基础知识、草图、轮廓、方向和拉伸开始。在此基础上，', '课程简介：本课程并非围绕简单地死记硬背按钮和命令展开。其目标是帮助你理解3D模型是如何创建的，为什么存在不同的建模功能，以及在开始构建之前如何选择正确的方案。我们将从3D空间的基础知识、草图、轮廓、方向和拉伸开始。在此基础上，你将探索重要的实体建模工具和概念，包括旋转、扫掠、曲面、镜像、阵列、凹陷以及其他实用的Fusion 360功能。在整个课程中，您将建立一个结构化的建模工作流程： 分析几何形状 → 制定建模计划 → 选择合适的特征 → 构建模型。您还将通过实际建模示例，帮助您超越单纯地跟随教程，开始做出自己的建模决策。课程将介绍曲面建模，您将学习如何利用曲面来创建和控制更复杂的几何形状。您将通过实际的曲面建模案例研究来应用这些概念。您将学习 Fusion 360 中组件和装配体的运作方式，并探索机械关系以及实际的卡扣设计技术，包括线性卡扣和扭转卡扣。累计时长 7 小时 31 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握设计软件的核心操作与高效工作流","理解版式、色彩、字体与视觉层级的基本原理","独立完成一套可放入作品集的完整设计项目","建立从需求沟通到设计交付的协作能力"]', '["零基础想入门设计的爱好者","需要系统提升视觉能力的运营与产品人员","设计专业在校学生"]', '["自备可运行设计软件的电脑","具备基础的审美观察与临摹耐心"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/b90e1cb5e1e02c8202232e7c1d25b6d24d6d5ae9.jpg', '["设计创意","UI设计","平面设计","Fusion","入门教程","从零开始进行"]', 27080, 9, 106, '4.4', 15, 'BV1xYnv6FEiG', '49.00', '78.40', 'CNY', 0, 0, 'standard', NULL, '巴托异界', 0, 'tenant', 'published', '2026-10-21T03:15:27.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
