    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1nh411s7rv', 'course-bili-bv1nh411s7rv', '100001', '0', 'BILI-DES-E6TBMG', 'course-category-design', 'instructor-bili-396491181', '传智教育Sketch全套教程，UI设计师需会的Sketch矢量绘图精品课', '47 讲完整课程 · 7 小时 29 分钟', 'Sketch是最强大的移动应用矢量绘图设计工具，对于网页设计和移动设计者来说，比PhotoShop好用N倍！尤其是在移动应用设计方面，Sketch 的优点在于使用简单，学习曲线低，并且功能更加强大易用，支持自动切图，', '课程简介：Sketch是最强大的移动应用矢量绘图设计工具，对于网页设计和移动设计者来说，比PhotoShop好用N倍！尤其是在移动应用设计方面，Sketch 的优点在于使用简单，学习曲线低，并且功能更加强大易用，支持自动切图，并且具有移动设计模板，能够大大节省设计师的时间和工作量，非常适合进行网站设计、移动应用设计、图标设计等。本教程会让你掌握如何使用Sketch绘制复杂图形以及Sketch设计APP界面技巧，切图标注技法，最后由项目深入浅出学习软件，最终通过Sketch完成APP项目。课程结构：共 6 章 47 讲，累计时长 7 小时 29 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握设计软件的核心操作与高效工作流","理解版式、色彩、字体与视觉层级的基本原理","独立完成一套可放入作品集的完整设计项目","建立从需求沟通到设计交付的协作能力"]', '["零基础想入门设计的爱好者","需要系统提升视觉能力的运营与产品人员","设计专业在校学生"]', '["自备可运行设计软件的电脑","具备基础的审美观察与临摹耐心"]', 'intermediate', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/e40722a9cf73ab96cf6fa29fab9a63fd0ea6230f.jpg', '["设计创意","UI设计","平面设计"]', 26949, 47, 4293, '4.3', 859, 'BV1Nh411S7rv', NULL, NULL, NULL, 1, 0, 'standard', NULL, '传智AI', 0, 'tenant', 'published', '2021-04-21T06:02:56.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
