INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1xsj96wexc', 'course-bili-bv1xsj96wexc', '100001', '0', 'BILI-DES-9FBUYL', 'course-category-design', 'instructor-bili-98989656', 'Blender 100章 系统教程：从零基础入门到3D动画制作', '101 讲完整课程 · 93 小时 57 分钟', '课程以 Blender 制作二次元风格角色动画为主线，从软件界面和基础建模开始，依次涉及 SD 角色建模、角色设计、Mint 与 Guardian 角色制作、着色器节点、道具和角色绑定，以及户外与室内背景搭建。', '课程简介：课程以 Blender 制作二次元风格角色动画为主线，从软件界面和基础建模开始，依次涉及 SD 角色建模、角色设计、Mint 与 Guardian 角色制作、着色器节点、道具和角色绑定，以及户外与室内背景搭建。动画部分从物理规律、重心变化、走跑循环和测试场景展开，再制作角色行走、奔跑、取物、躲避与战斗等场景，并涵盖几何节点、流体模拟、粒子、魔法阵和激光效果，最后进行合成修正、剪辑与渲染。课程面向希望开始用 Blender 制作 3D 作品的初学者、想创作个人作品的中级创作者，以及独立制作动画有困难的学习者。课程使用 Blender 3.3；部分纹理绘制可能用到 Clip Studio Paint 或 Photoshop。—————————————————————— 1.课程来自公开互联网，仅供学习交流，版权归原作者所有。课程内容及配套资源以网站页面最终标注为准。3.课程配音字幕有较大问题请联系我紧急处理。4.有好的课程也可以私我 课程编号 260471（如果上面地址失效。cgtuto.com 请输入编号搜索可直接定位课程） 课程结构：共 13 章 101 讲，累计时长 93 小时 57 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握设计软件的核心操作与高效工作流","理解版式、色彩、字体与视觉层级的基本原理","独立完成一套可放入作品集的完整设计项目","建立从需求沟通到设计交付的协作能力"]', '["零基础想入门设计的爱好者","需要系统提升视觉能力的运营与产品人员","设计专业在校学生"]', '["自备可运行设计软件的电脑","具备基础的审美观察与临摹耐心"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/2a27b2a5b90363c46879427bbaa24eba93120d87.jpg', '["设计创意","UI设计","平面设计","Blender","100章","系统教程"]', 338238, 101, 325, '4.5', 132, 'BV1XsJ96WExc', '199.00', '318.40', 'CNY', 0, 0, 'standard', NULL, 'LiuVFX', 0, 'tenant', 'published', '2026-10-16T06:26:37.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
