-- ── BILI-DES-U50UC4 · blender课堂 ──

INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-5795520', 'course-bili-season-5795520', '100001', '0', 'BILI-DES-U50UC4', 'course-category-design', 'instructor-bili-3546685005368073', 'blender课堂', '202 讲完整课程 · 2172 小时 41 分钟', '学习如何在Blender中创建专业的3D产品渲染图和动画，并将您的技能转化为有价值的自由职业服务。本课程将带您走完完整的3D产品可视化工作流程，从构建和准备产品模型，到创建逼真的材质、专业灯光、相机设置、照片级真实感渲染', '课程简介：学习如何在Blender中创建专业的3D产品渲染图和动画，并将您的技能转化为有价值的自由职业服务。本课程将带您走完完整的3D产品可视化工作流程，从构建和准备产品模型，到创建逼真的材质、专业灯光、相机设置、照片级真实感渲染以及引人入胜的产品动画。您将学习可应用于广泛产品（包括电子产品、化妆品、包装、配件、家用电器以及其他电子商务产品）的实用技巧。本课程专注于创建干净、高端的视觉效果，可用于广告、电子商务、作品集和客户项目。但创作出色的3D作品仅仅是旅程的一部分。本课程还包含一份自由职业指南，旨在帮助你将Blender技能转化为收入。你将学习如何建立强大的产品可视化作品集、专业地展示你的服务、寻找潜在客户、撰写有效的提案、与客户沟通、定价你的作品，以及作为一名自由职业3D艺术家不断成长。累计时长 2172 小时 41 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握设计软件的核心操作与高效工作流","理解版式、色彩、字体与视觉层级的基本原理","独立完成一套可放入作品集的完整设计项目","建立从需求沟通到设计交付的协作能力"]', '["零基础想入门设计的爱好者","需要系统提升视觉能力的运营与产品人员","设计专业在校学生"]', '["自备可运行设计软件的电脑","具备基础的审美观察与临摹耐心"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/f04ed7a93d97aa3e973ff70baa2a00dcf4ed0334.jpg', '["设计创意","UI设计","平面设计","blender课堂"]', 7821660, 202, 294, '4.5', 144, 'BV1RMpe65EQ8', NULL, NULL, NULL, 1, 0, 'standard', NULL, '巴托异界', 0, 'tenant', 'published', '2026-10-10T03:22:58.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
